// План specs/clients-import.md 1.1–1.3 (#4030e4, реджект 2 — окно Import clients). PROD, admin, компания «test», EN. @prod-safe: файл выбирается,
// но импорт НЕ выполняется (Cancel) — в базе ничего не появляется.
// 1.1 — десктоп 1280: окно широкое (≥ 80% экрана), Preview без бокового скролла, блок «Found in the file», «Also import»: Notes / Tags / Workiz client ID
//       включены, «N new clients will be added.», нет выпадающих списков для базовых полей.
// 1.2 — нераспознанная колонка «Mobile»: список только для неё, с примером значения, варианты «Don't import» / «Add to notes» / поля; пустых колонок нет.
// 1.3 — телефон 390 (@android): окно не ломается — нет горизонтальной прокрутки страницы, кнопки «Cancel» / «Import N clients» видны.
// Факты 17.11: окно 1152 px, Found in the file, Also import, нераспознанная колонка, HE и 390 ок.
import { test, expect } from '../../fixtures';
import { ROLE, importDialog, mobileCsv, openImportWithFile, prepare, stamp, workizCsv, workizRows } from './import-helpers';

test.describe('Import clients window (#4030e4)', () => {
  test('Wide window: "Found in the file", "Also import" Notes/Tags/Workiz client ID on, Preview without side scroll, no per-field dropdowns #4030e4 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await page.setViewportSize({ width: 1280, height: 800 });
    await prepare(page);
    const dialog = await openImportWithFile(page, `4030e4-${stamp()}.csv`, workizCsv(workizRows(stamp())));

    const box = (await dialog.boundingBox())!;
    expect(box.width, 'окно занимает большую часть ширины (≥ 80% от 1280)').toBeGreaterThanOrEqual(1280 * 0.8);

    await expect(dialog.getByText('3 rows in the file')).toBeVisible();
    for (const field of ['First name', 'Last name', 'Company', 'Phone', 'Email', 'Address', 'City', 'State', 'ZIP']) {
      await expect(dialog.getByText(field, { exact: true }).first(), `«${field}» найдено в файле`).toBeVisible();
    }
    for (const opt of ['Notes', 'Tags', 'Workiz client ID']) {
      await expect(dialog.getByRole('checkbox', { name: opt }), `«Also import» ${opt} включён`).toBeChecked();
    }
    await expect(dialog.getByText('3 new clients will be added.')).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'Import 3 clients' })).toBeEnabled();
    await expect(dialog.getByRole('combobox'), 'базовые поля переносятся автоматически — списков выбора колонок нет').toHaveCount(0);

    // Preview без бокового скролла
    const overflow = await dialog.evaluate((el) => [...el.querySelectorAll<HTMLElement>('*')].filter((n) => n.scrollWidth > n.clientWidth + 1 && ['auto', 'scroll'].includes(getComputedStyle(n).overflowX)).length);
    expect(overflow, 'в окне нет горизонтально прокручиваемых блоков (Preview без бокового скролла)').toBe(0);

    await dialog.getByRole('button', { name: 'Cancel' }).click();
    await expect(dialog).toBeHidden();
  });

  test('Unrecognized column "Mobile": a selector only for it, with a sample value and options #4030e4 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await page.setViewportSize({ width: 1280, height: 800 });
    await prepare(page);
    const dialog = await openImportWithFile(page, `4030e4-mobile-${stamp()}.csv`, mobileCsv(stamp()));

    await expect(dialog.getByText(/Columns we didn't recognize/)).toBeVisible();
    await expect(dialog.getByText('Mobile', { exact: true })).toBeVisible();
    await expect(dialog.getByText('3055550184'), 'пример значения колонки').toBeVisible();
    const selects = dialog.getByRole('combobox');
    await expect(selects, 'список только для нераспознанной колонки').toHaveCount(1);
    await expect(selects.first()).toContainText("Don't import");
    await selects.first().click();
    for (const option of ["Don't import", 'Add to notes', 'Phone 2']) {
      await expect(page.getByRole('option', { name: option, exact: true }), `вариант «${option}»`).toBeVisible();
    }
    await page.keyboard.press('Escape');
    await dialog.getByRole('button', { name: 'Cancel' }).click();
  });

  test('Phone 390: the Import clients window does not break (no page side scroll, buttons visible) #4030e4 @android @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await prepare(page);
    const dialog = await openImportWithFile(page, `4030e4-m-${stamp()}.csv`, workizCsv(workizRows(stamp())));
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1), 'нет горизонтальной прокрутки страницы').toBe(true);
    await expect(dialog.getByRole('button', { name: 'Cancel' })).toBeInViewport();
    await expect(dialog.getByRole('button', { name: /^Import \d+ clients?$/ })).toBeAttached();
    await dialog.getByRole('button', { name: 'Cancel' }).click();
    await expect(importDialog(page)).toBeHidden();
  });
});
